/* ------------------------------------------------------------------ public API (in-process) */

/** What other modules may call in-process: `ctx.use('wallet')` (or `ctx.tryUse` for an optional dependency). */
export interface WalletPublicApi {
  /** Available balance and soonest expiry, for checkout step 4 'Use my Marketly credit'. Used by: checkout, customers, graphql. */
  getBalance(customerId: string): Promise<CreditBalance>;
  /** Reserve credit for a quote; earliest-expiring lots first. Fails with INSUFFICIENT_CREDIT. Used by: checkout, payments. */
  holdCredit(customerId: string, quoteId: string, amount: common.Money, idempotencyKey: string): Promise<CreditHold>;
  /** Turn a hold into a use when the order is accepted. Used by: payments, checkout. */
  captureHold(holdId: string, orderId: string): Promise<CreditHold>;
  /** Release a hold on payment failure or quote expiry. Used by: payments, checkout. */
  releaseHold(holdId: string): Promise<CreditHold>;
  /** Refund to store credit (customer's choice) or return the credit part of a refunded order. Called by returns for return refunds to store credit and by payments for the refunds it executes (other origins with destination store_credit, and the credit part of a mixed tender). Idempotent per refundId; the payment tender split decides how much goes back to credit. Used by: payments, returns. */
  creditRefund(input: { customerId: string, refundId: string, orderId: string, amount: common.Money, reason: string }, idempotencyKey: string): Promise<LedgerEntry>;
  /** Goodwill credit from a support case or order; above the actor's limit it becomes pending approval. Used by: support. */
  grantGoodwill(input: GoodwillInput, actor: common.Actor, idempotencyKey: string): Promise<GoodwillGrant>;
  /** Staff view of a customer's credit: balance, lots, goodwill in the last 30 days against the per-customer limit, and pending grants (GET /admin/wallet/customers/{customerId}). Used by: graphql. */
  getCustomerWallet(customerId: string): Promise<CustomerWalletAdmin>;
}

